def transform(grid):
    h_boundary = next(i for i, row in enumerate(grid) if all(v == 7 for v in row))
    v_boundaries = sorted([c for c in range(len(grid[0])) if all(grid[r][c] == 7 for r in range(len(grid)))])
    colored = 4
    output = [[5] * 4, [5] * 4]

    # Top row regions (rows 0 to h_boundary-1)
    for c_idx in range(4):
        if c_idx == 0:
            c_start, c_end = 0, v_boundaries[0]
        elif c_idx == 1:
            c_start, c_end = v_boundaries[0] + 1, v_boundaries[1]
        elif c_idx == 2:
            c_start, c_end = v_boundaries[1] + 1, v_boundaries[2]
        else:
            c_start, c_end = v_boundaries[2] + 1, len(grid[0])

        count = sum(grid[r][c] for r in range(0, h_boundary) for c in range(c_start, c_end) if grid[r][c] == colored)
        if count > 1:
            output[0][c_idx] = 1

    # Bottom row regions (rows h_boundary+1 to end)
    for c_idx in range(4):
        if c_idx == 0:
            c_start, c_end = 0, v_boundaries[0]
        elif c_idx == 1:
            c_start, c_end = v_boundaries[0] + 1, v_boundaries[1]
        elif c_idx == 2:
            c_start, c_end = v_boundaries[1] + 1, v_boundaries[2]
        else:
            c_start, c_end = v_boundaries[2] + 1, len(grid[0])

        count = sum(grid[r][c] for r in range(h_boundary + 1, len(grid)) for c in range(c_start, c_end) if grid[r][c] == colored)
        if count > 1:
            output[1][c_idx] = 1

    return output

