def transform(grid):
    """Transform the grid by counting colored cells in each region."""
    h_boundary = next(i for i, row in enumerate(grid) if all(v == 7 for v in row))
    v_boundaries = sorted([c for c in range(len(grid[0])) if all(grid[r][c] == 7 for r in range(len(grid)))])
    colored = 4  # The colored value to count
    output = [[5] * 4, [5] * 4]

    # Process both top and bottom regions
    for row_offset in [0, 1]:
        row_start = 0 if row_offset == 0 else h_boundary + 1
        row_end = h_boundary if row_offset == 0 else len(grid)

        for c_idx in range(4):
            if c_idx == 0:
                c_start, c_end = 0, v_boundaries[0]
            elif c_idx == 1:
                c_start, c_end = v_boundaries[0] + 1, v_boundaries[1]
            elif c_idx == 2:
                c_start, c_end = v_boundaries[1] + 1, v_boundaries[2]
            else:
                c_start, c_end = v_boundaries[2] + 1, len(grid[0])

            # Count colored cells in this region
            count = 0
            for r in range(row_start, row_end):
                for c in range(c_start, c_end):
                    if grid[r][c] == colored:
                        count += 1

            if count > 1:
                output[row_offset][c_idx] = 1

    return output

