code = '''
def transform_grid(grid):
    """
    Count colored cells in each region bounded by separator lines.
    Regions with > 1 colored cell output "1", others output background value.
    """
    # Find horizontal boundary
    h_row = next(i for i, row in enumerate(grid) if all(v == grid[i][0] for v in row))

    # Find vertical boundaries
    v_cols = [c for c in range(len(grid[0])) if all(grid[r][c] == grid[h_row][c] for r in range(len(grid)))]

    # Determine background and colored values
    all_vals = {}
    for row in grid:
        for val in row:
            all_vals[val] = all_vals.get(val, 0) + 1
    boundary_val = grid[h_row][0]
    non_boundary = [v for v in all_vals if v != boundary_val]

    # Colored value = least common non-boundary value
    colored_val = min(non_boundary, key=lambda v: all_vals[v])
    background_val = next(v for v in non_boundary if v != colored_val)

    # Define row and column segments (skipping boundaries)
    row_segments = [(0, h_row), (h_row + 1, len(grid))]
    col_segments = []
    start = 0
    for v_col in v_cols:
        if v_col > start:
            col_segments.append((start, v_col - 1))
        start = v_col + 1
    if start < len(grid[0]):
        col_segments.append((start, len(grid[0]) - 1))

    # Build output grid
    output = [[background_val] * len(col_segments) for _ in range(len(row_segments))]

    for r_idx, (r_start, r_end) in enumerate(row_segments):
        for c_idx, (c_start, c_end) in enumerate(col_segments):
            count = sum(1 for r in range(r_start, r_end) for c in range(c_start, c_end + 1) if grid[r][c] == colored_val)
            if count > 1:
                output[r_idx][c_idx] = 1

    return output
'''

